G=load()
inp=G['Test input']; n=len(inp[0]); c=inp[0].index(2)
out=[[0]*n for _ in range(n)]
# 2s: V arms
for i in range(min(c,n)):
    for jj in (c-i,c+i):
        out[i][jj]=2
    # stop if arms go out of bounds
    if c-i<0: break
# 1s: continuation of each arm past the bottom row, reversed horizontal direction
for i in range(1,c+1):
    for j in (c+i,c-i):
        if i<c: continue
        # from endpoint (c,j): continue with horiz direction flipped
        d = 1 if j==c-i else -1
        for r in range(c+1,n):
            j2=j+d*(r-c)
            if 0<=j2<n: out[r][j2]=1
print(json.dumps(out))

